from itertools import chain, islice

def take(n, it):
    return list(islice(it, n))

def flatten(list_of_lists):
    return list(chain.from_iterable(list_of_lists))

def unique(items):
    seen = {}
    for x in items:
        if x not in seen:
            seen[x] = True
            yield x

print(take(3, iter(range(10))))
print(flatten([[1, 2], [3], []]))
print(list(unique([3, 1, 3, 2, 1])))
